import sys
input = sys.stdin.read
from functools import lru_cache

def solve(r, s, p):
    @lru_cache(None)
    def dp(r, s, p):
        if r == 0 and s == 0:
            return (0, 0, 1)
        if r == 0 and p == 0:
            return (0, 1, 0)
        if s == 0 and p == 0:
            return (1, 0, 0)

        total_pairs = r * s + s * p + p * r
        result_r = result_s = result_p = 0

        if r > 0 and s > 0:
            pr = (r * s) / total_pairs
            res_r, res_s, res_p = dp(r, s - 1, p)
            result_r += pr * res_r
            result_s += pr * res_s
            result_p += pr * res_p

        if s > 0 and p > 0:
            ps = (s * p) / total_pairs
            res_r, res_s, res_p = dp(r, s, p - 1)
            result_r += ps * res_r
            result_s += ps * res_s
            result_p += ps * res_p

        if p > 0 and r > 0:
            pp = (p * r) / total_pairs
            res_r, res_s, res_p = dp(r - 1, s, p)
            result_r += pp * res_r
            result_s += pp * res_s
            result_p += pp * res_p

        return (result_r, result_s, result_p)

    return dp(r, s, p)

data = input().strip().split()
r, s, p = map(int, data)
result_r, result_s, result_p = solve(r, s, p)
print(f"{result_r:.12f}")
print(f"{result_s:.12f}")
print(f"{result_p:.12f}")

