import sys
input = sys.stdin.read
data = input().split()

r, s, p = map(int, data)

def calc_prob(a, b, c):
    dp = [[[[0.0] * 101 for _ in range(101)] for _ in range(101)] for _ in range(2)]
    dp[0][a][b][c] = 1.0

    for x in range(a, 101):
        for y in range(b, 101):
            for z in range(c, 101):
                total = x * y + y * z + z * x
                for i, j, k in [(x, y, z), (x, z, y), (y, x, z)]:
                    if i and j:
                        dp[1][i-1][j][k] += dp[0][i][j][k] * i * j / total
                    if j and k:
                        dp[1][i][j-1][k] += dp[0][i][j][k] * j * k / total
                    if k and i:
                        dp[1][i][j][k-1] += dp[0][i][j][k] * k * i / total
                if total == 0:
                    continue
                for i, j, k in [(x, y, z), (x, z, y), (y, x, z)]:
                    dp[1][i][j][k] += dp[0][i][j][k] * (i * j + j * k + k * i) / total
    return dp[1]

results = calc_prob(r, s, p)

for result in results[1:]:
    print("{:.12f}".format(result))

